        exams.append((s_i, d_i, c_i))
        index += 3

    # dp[day][passed_exams][prepared_exams] = (is_possible, schedule)
    dp = [[[None for _ in range(1 << m)] for _ in range(m + 1)] for _ in range(n + 1)]

    # Initial state: 0 days, 0 exams passed, 0 exams prepared
    dp[0][0][0] = (True, [])

    for day in range(n):
        for passed_exams in range(m + 1):
            for prepared_exams in range(1 << m):
                if dp[day][passed_exams][prepared_exams] is None:
                    continue

                is_possible, schedule = dp[day][passed_exams][prepared_exams]

                if not is_possible:
                    continue

                # Option 1: Do nothing (rest)
                if dp[day + 1][passed_exams][prepared_exams] is None:
                    dp[day + 1][passed_exams][prepared_exams] = (True, schedule + [0])

                # Option 2: Pass an exam
                if passed_exams < m:
                    if dp[day + 1][passed_exams + 1][prepared_exams] is None:
                        dp[day + 1][passed_exams + 1][prepared_exams] = (True, schedule + [passed_exams + 1])

                # Option 3: Prepare for an exam
                for i in range(m):
                    if not (prepared_exams & (1 << i)):
                        s_i, d_i, c_i = exams[i]
                        if day >= s_i and day < d_i:
                            # Check if we have enough days to prepare
                            days_needed = 0
                            for j in range(day, d_i):
                                if j >= s_i:
                                    days_needed += 1
                            if days_needed <= c_i:
                                new_prepared_exams = prepared_exams | (1 << i)
                                if dp[day + 1][passed_exams][new_prepared_exams] is None:
                                    dp[day + 1][passed_exams][new_prepared_exams] = (True, schedule + [i + 1])

    # Find the solution
    for passed_exams in range(m + 1):
        for prepared_exams in range(1 << m):
            if dp[n][passed_exams][prepared_exams] is not None:
                is_possible, schedule = dp[n][passed_exams][prepared_exams]
                if is_possible and passed_exams == m:
                    print(" ".join(map(str, schedule)))
                    return

    print(-1)
